create extension if not exists pgcrypto;
create table if not exists public.platform_core(id uuid primary key default gen_random_uuid(),tenant_name text not null default 'Demo Desa',province text not null default 'Jawa Barat',regency text not null default 'Kabupaten Demo',district text not null default 'Kecamatan Demo',village text not null default 'Desa Demo',village_code text,status text not null default 'PILOT',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.demo_requests(id uuid primary key default gen_random_uuid(),request_number text unique not null,citizen_name text not null,service_name text not null,scope_label text not null,status text not null default 'SUBMITTED',classification text not null default 'INTERNAL',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.demo_events(id uuid primary key default gen_random_uuid(),module text not null,title text not null,detail text not null,severity text not null default 'INFO',created_at timestamptz not null default now());
create table if not exists public.demo_documents(id uuid primary key default gen_random_uuid(),document_number text unique not null,title text not null,document_type text not null,status text not null default 'DRAFT',signer_label text,verification_code text unique not null,created_at timestamptz not null default now());
create table if not exists public.demo_signatures(id uuid primary key default gen_random_uuid(),document_id uuid not null references public.demo_documents(id),signer_name text not null,signer_role text not null,status text not null default 'PENDING',document_hash text not null,signed_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.ai_companion_interactions(id uuid primary key default gen_random_uuid(),session_id text,question text not null,answer text,source_count int not null default 0,confidence numeric(5,4),feedback text,feedback_note text,status text not null default 'ANSWERED',created_at timestamptz not null default now());
create table if not exists public.ai_learning_queue(id uuid primary key default gen_random_uuid(),kind text not null,title text not null,proposal text not null,evidence text,source_interaction_id uuid references public.ai_companion_interactions(id),status text not null default 'CANDIDATE',created_at timestamptz not null default now(),reviewed_at timestamptz);
create table if not exists public.ai_companion_memory(id uuid primary key default gen_random_uuid(),memory_key text unique not null,memory_value text not null,memory_type text not null default 'SYSTEM',version int not null default 1,active boolean not null default true,updated_at timestamptz not null default now());
create table if not exists public.ai_knowledge_items(id text primary key,title text not null,content text not null,source text not null,section text not null,approved boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.exchange_datasets(id uuid primary key default gen_random_uuid(),dataset_code text unique not null,name text not null,description text not null,source_system text not null default 'RT_RW_SID_CONNECT',version text not null default '1.0.0',classification text not null default 'INTERNAL',purpose text not null,scope_type text not null default 'VILLAGE',authority text not null,status text not null default 'ACTIVE',schema_definition jsonb not null default '{}'::jsonb,masking_policy jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.exchange_requests(id uuid primary key default gen_random_uuid(),request_number text unique not null,consumer_system text not null,dataset_code text not null,purpose_code text not null,requested_scope text not null,requested_fields jsonb not null default '[]'::jsonb,status text not null default 'PENDING_APPROVAL',requested_by uuid references auth.users(id),approved_by uuid references auth.users(id),approved_at timestamptz,decision_note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.exchange_exports(id uuid primary key default gen_random_uuid(),export_number text unique not null,request_id uuid references public.exchange_requests(id),dataset_code text not null,dataset_version text not null,consumer_system text not null,purpose_code text not null,scope_label text not null,classification text not null,row_count int not null default 0,payload jsonb not null default '{}'::jsonb,data_hash text,generated_at timestamptz not null default now(),expires_at timestamptz,status text not null default 'GENERATED');
create table if not exists public.exchange_audit_logs(id uuid primary key default gen_random_uuid(),event_type text not null,actor uuid references auth.users(id),consumer_system text,dataset_code text,request_id uuid references public.exchange_requests(id),export_id uuid references public.exchange_exports(id),purpose_code text,scope_label text,result text not null default 'SUCCESS',metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
insert into public.platform_core(tenant_name) select 'Demo Desa' where not exists(select 1 from public.platform_core);
insert into public.demo_events(module,title,detail) select 'CORE','Platform pilot siap diperiksa','RT/RW–SID CONNECT v2.0 telah dipindahkan ke free-first architecture.' where not exists(select 1 from public.demo_events where title='Platform pilot siap diperiksa');
insert into public.demo_documents(document_number,title,document_type,status,signer_label,verification_code) select 'DOC-2026-0001','Surat Keterangan Domisili','SURAT','READY','Kepala Desa','VERIFY-DEMO01' where not exists(select 1 from public.demo_documents where document_number='DOC-2026-0001');
insert into public.exchange_datasets(dataset_code,name,description,purpose,authority,schema_definition,masking_policy) values('COMMUNITY_NEEDS','Community Needs','Verified community needs for program matching','GPFFE opportunity matching','RT/RW → Village Verification Chain','{"fields":["need_category","need_count","priority","scope_label","verification_status"]}','{"identity":"excluded","sensitive_free_text":"masked"}') on conflict(dataset_code) do nothing;
insert into public.exchange_datasets(dataset_code,name,description,purpose,authority,schema_definition,masking_policy) values('COMMUNITY_PROFILE_AGGREGATE','Community Profile Aggregate','Aggregated demographic and economic indicators','GPFFE needs assessment','Village Data Governance Authority','{"fields":["population_total","households_total","age_groups","employment","umkm_count"]}','{"nik":"excluded","phone":"excluded","address_detail":"excluded"}') on conflict(dataset_code) do nothing;
alter table public.platform_core enable row level security; alter table public.demo_requests enable row level security; alter table public.demo_events enable row level security; alter table public.demo_documents enable row level security; alter table public.demo_signatures enable row level security; alter table public.ai_companion_interactions enable row level security; alter table public.ai_learning_queue enable row level security; alter table public.ai_companion_memory enable row level security; alter table public.ai_knowledge_items enable row level security; alter table public.exchange_datasets enable row level security; alter table public.exchange_requests enable row level security; alter table public.exchange_exports enable row level security; alter table public.exchange_audit_logs enable row level security;
create policy "public platform summary" on public.platform_core for select to anon,authenticated using(true);
create policy "public demo events" on public.demo_events for select to anon,authenticated using(true);
create policy "public exchange catalog" on public.exchange_datasets for select to anon,authenticated using(status='ACTIVE');
create policy "authenticated requests select" on public.demo_requests for select to authenticated using(true);
create policy "authenticated requests insert" on public.demo_requests for insert to authenticated with check(true);
create policy "authenticated documents" on public.demo_documents for select,insert to authenticated using(true) with check(true);
create policy "authenticated signatures" on public.demo_signatures for select,insert to authenticated using(true) with check(true);
create policy "own exchange requests" on public.exchange_requests for select,insert to authenticated using(requested_by=auth.uid()) with check(requested_by=auth.uid());
create policy "authenticated exports" on public.exchange_exports for select to authenticated using(true);
create policy "own exchange audit" on public.exchange_audit_logs for select to authenticated using(actor=auth.uid());
revoke all on table public.demo_requests,public.demo_documents,public.demo_signatures,public.exchange_requests,public.exchange_exports,public.exchange_audit_logs from anon;
grant select on public.platform_core,public.demo_events,public.exchange_datasets to anon,authenticated;
grant select,insert on public.demo_requests,public.demo_documents,public.demo_signatures,public.exchange_requests to authenticated;
grant select on public.exchange_exports,public.exchange_audit_logs to authenticated;